package com.ragnarok93.bbsremix.patch

/** Generated non-game payloads. Run reference/sync_payloads.py after editing the Python oracle. */
internal object Stage5Payloads {
    const val S2_FILE_OFFSET = 0x0036BE80
    const val S2_VA = 0x08B6EE80
    const val S2_CAPTURE_PAD_VA = 0x08B6EE80
    const val S2_RIGHT_X_VA = 0x08B6EED4
    const val S2_RIGHT_Y_VA = 0x08B6EEE0

    const val S4_FILE_OFFSET = 0x0036D000
    const val S4_VA = 0x08B70000
    const val S4_POST_INPUT_VA = 0x08B70000
    const val S4_TELEMETRY_VA = 0x08B709F0
    const val S4_CONFIG_VA = 0x08B70A20
    const val S4_CONFIG_OFFSET = S4_CONFIG_VA - S4_VA
    const val S4_CAMERA_DISTANCE_VA = 0x08B70A24
    const val S4_CAMERA_DISTANCE_OFFSET = S4_CAMERA_DISTANCE_VA - S4_VA
    const val S4_RING_VA = 0x08B70A40

    const val S5_WRAPPER_VA = 0x08B71280
    const val S5_WRAPPER_OFFSET = S5_WRAPPER_VA - S4_VA
    const val S5_PASSIVES_CONFIG_VA = 0x08B71300
    const val S5_PASSIVES_CONFIG_OFFSET = S5_PASSIVES_CONFIG_VA - S4_VA
    const val S5_SEGMENT_PAD = 0x00001320
    const val S5_CRITICAL_PASSIVE_MASK = 0x04008300
    const val ORIGINAL_LOAD1_VA = 0x08BB4780

    const val CAMERA_FREE_HEIGHT_VA = 0x08B59F24
    const val CAMERA_LOCK_HEIGHT_VA = 0x08B59F54
    const val CAMERA_FREE_HEIGHT_ORIG = 1.5f
    const val CAMERA_LOCK_HEIGHT_ORIG = 1.0f

    val s2Blob: ByteArray = hex(
        "e0ffbd271c00bfaf1800b0af218080004e5b2c0e00000000b708083c8000092480000a24050040180000000003000012000000000a0009920b000a9204ef09a105ef0aa11800b08f1c00bf8f0800e0032000bd27b708083c0300001004ef0291b708083c05ef029180ff42240000824420008046003c083c001088440800e003020002468080"
    )
    val s4Blob: ByteArray = hex(
        ""
    )
    val s5WrapperBlob: ByteArray = hex(
        "00c02d0e00000000b708083c00130991010029311200201100000000b608083cb0a4088d0e00001100000000a800088d0b00001100000000f209093c015f299103000a2406002a15000000003000098d00040a3c00834a3525482a01300009ad425a200a00000000"
    )

    val s2NewSegmentSize: Int
        get() = (S2_FILE_OFFSET + s2Blob.size) - 0x1018

    private fun hex(value: String): ByteArray {
        val compact = value.filterNot(Char::isWhitespace)
        require(compact.length % 2 == 0) { "Odd-length hex payload" }
        return ByteArray(compact.length / 2) { index ->
            compact.substring(index * 2, index * 2 + 2).toInt(16).toByte()
        }
    }
}

